namespace ion.compiler.CodeGen.Emitters;

using System.Text;

/// <summary>
/// Rust реализация ICodeEmitter.
/// Генерирует синтаксические конструкции Rust.
/// </summary>
public sealed class RustEmitter : ICodeEmitter
{
    public string Language => "Rust";
    public string FileExtension => ".rs";
    public string GeneratedCodeAttribute => ""; // Rust doesn't have generated code attributes

    private const string AutoGeneratedHeader =
        """
        //------------------------------------------------------------------------------
        // <auto-generated>
        //     This code was generated by a code generation tool.
        //     Changes to this file may cause incorrect behavior and will be lost
        //     if the code is regenerated.
        //
        //     Generator: IonPath Codegen
        // </auto-generated>
        //------------------------------------------------------------------------------
        #![allow(dead_code, unused_imports, non_camel_case_types)]
        """;

    public string FileHeader(string? @namespace = null)
    {
        return AutoGeneratedHeader;
    }

    public string WrapInNamespace(string @namespace, string content)
    {
        // Rust uses mod blocks, but for generated code we just put it all at crate level
        return content;
    }

    // ═══════════════════════════════════════════════════════════════════
    // TYPE DECLARATIONS
    // ═══════════════════════════════════════════════════════════════════

    public string EnumDeclaration(string name, IEnumerable<EnumMember> members, EnumOptions? options = null, string? doc = null)
    {
        var baseType = options?.BaseType ?? "i32";
        var sb = new StringBuilder();
        sb.Append(DocComment(doc));
        sb.AppendLine($"#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]");
        sb.AppendLine($"#[repr({baseType})]");
        sb.AppendLine($"pub enum {name} {{");
        foreach (var m in members)
        {
            sb.Append(DocComment(m.Doc, Indent(1)));
            sb.AppendLine($"    {m.Name} = {m.Value},");
        }
        sb.AppendLine("}");
        return sb.ToString();
    }

    public string FlagsDeclaration(string name, string? baseType, IEnumerable<EnumMember> members, string? doc = null)
    {
        var sb = new StringBuilder();
        sb.Append(DocComment(doc));
        sb.AppendLine($"#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]");
        sb.AppendLine($"pub struct {name}(pub {baseType ?? "u32"});");
        sb.AppendLine();
        sb.AppendLine($"impl {name} {{");
        foreach (var m in members)
        {
            sb.Append(DocComment(m.Doc, Indent(1)));
            sb.AppendLine($"    pub const {m.Name}: Self = Self({m.Value});");
        }
        sb.AppendLine("}");
        return sb.ToString();
    }

    public string MessageDeclaration(string name, IEnumerable<FieldDecl> fields, string? doc = null)
    {
        var sb = new StringBuilder();
        sb.Append(DocComment(doc));
        sb.AppendLine("#[derive(Debug, Clone, PartialEq)]");
        sb.AppendLine($"pub struct {name} {{");
        foreach (var f in fields)
        {
            sb.Append(DocComment(f.Doc, Indent(1)));
            sb.AppendLine($"    pub {FormatIdentifier(f.Name)}: {f.Type},");
        }
        sb.AppendLine("}");
        return sb.ToString();
    }

    public string TypedefDeclaration(string name, string underlyingType, string? doc = null)
    {
        return $"{DocComment(doc)}pub type {name} = {underlyingType};";
    }

    public string ServiceInterfaceDeclaration(string name, IEnumerable<MethodDecl> methods, string? baseInterface = null, string? doc = null)
    {
        var sb = new StringBuilder();
        sb.Append(DocComment(doc));
        sb.AppendLine("#[async_trait::async_trait]");
        sb.AppendLine($"pub trait {name}: Send + Sync {{");
        foreach (var m in methods)
        {
            var args = string.Join(", ", m.Parameters.Select(p => $"{FormatIdentifier(p.Name)}: {p.Type}"));
            var selfArg = "&self";
            sb.Append(DocComment(m.Doc, Indent(1), m.DocParams));
            sb.AppendLine($"    async fn {FormatIdentifier(m.Name)}({selfArg}, {args}) -> Result<{m.ReturnType}, ion_rustcore::IonError>;");
        }
        sb.AppendLine("}");
        return sb.ToString();
    }

    public string ClassDeclaration(ClassDecl decl)
    {
        // Rust doesn't have classes; we generate struct + impl
        var sb = new StringBuilder();
        sb.Append(DocComment(decl.Doc));
        sb.AppendLine($"pub struct {decl.Name} {{");
        if (decl.Fields != null)
        {
            foreach (var f in decl.Fields)
            {
                sb.Append(DocComment(f.Doc, Indent(1)));
                sb.AppendLine($"    pub {FormatIdentifier(f.Name)}: {f.Type},");
            }
        }
        sb.AppendLine("}");
        return sb.ToString();
    }

    // ═══════════════════════════════════════════════════════════════════
    // UNION TYPES
    // ═══════════════════════════════════════════════════════════════════

    public string UnionBaseDeclaration(string name, IEnumerable<string> caseNames, IEnumerable<FieldDecl>? sharedFields = null, string? doc = null)
    {
        var sb = new StringBuilder();
        sb.Append(DocComment(doc));
        sb.AppendLine("#[derive(Debug, Clone, PartialEq)]");
        sb.AppendLine($"pub enum {name} {{");
        foreach (var caseName in caseNames)
            sb.AppendLine($"    {caseName}({caseName}),");
        sb.AppendLine("}");

        // Add union_index helper
        sb.AppendLine();
        sb.AppendLine($"impl {name} {{");
        sb.AppendLine("    pub fn union_index(&self) -> u32 {");
        sb.AppendLine("        match self {");
        var idx = 0;
        foreach (var caseName in caseNames)
        {
            sb.AppendLine($"            Self::{caseName}(_) => {idx},");
            idx++;
        }
        sb.AppendLine("        }");
        sb.AppendLine("    }");
        sb.AppendLine("}");
        return sb.ToString();
    }

    public string UnionCaseDeclaration(string caseName, string unionName, int caseIndex, IEnumerable<FieldDecl> fields, string? doc = null)
    {
        // Union cases are standalone structs in Rust
        var sb = new StringBuilder();
        sb.Append(DocComment(doc));
        sb.AppendLine("#[derive(Debug, Clone, PartialEq)]");
        sb.AppendLine($"pub struct {caseName} {{");
        foreach (var f in fields)
        {
            sb.Append(DocComment(f.Doc, Indent(1)));
            sb.AppendLine($"    pub {FormatIdentifier(f.Name)}: {f.Type},");
        }
        sb.AppendLine("}");
        return sb.ToString();
    }

    // ═══════════════════════════════════════════════════════════════════
    // TYPE NAMES
    // ═══════════════════════════════════════════════════════════════════

    public string NullableType(string innerType) => $"Option<{innerType}>";
    public string ArrayType(string innerType) => $"Vec<{innerType}>";
    public string GenericType(string baseName, IEnumerable<string> typeArgs)
        => $"{baseName}<{string.Join(", ", typeArgs)}>";
    public string AsyncReturnType(string? innerType)
        => innerType == null ? "()" : innerType;
    public string StreamReturnType(string innerType)
        => $"Pin<Box<dyn Stream<Item = Result<{innerType}, IonError>> + Send>>";
    public string StreamInputType(string innerType)
        => $"Pin<Box<dyn Stream<Item = {innerType}> + Send>>";

    // ═══════════════════════════════════════════════════════════════════
    // FORMATTING HELPERS
    // ═══════════════════════════════════════════════════════════════════

    public string Indent(int level) => new string(' ', level * 4);

    public string FormatIdentifier(string name)
    {
        // Convert camelCase to snake_case for Rust
        var sb = new StringBuilder();
        for (int i = 0; i < name.Length; i++)
        {
            var c = name[i];
            if (char.IsUpper(c) && i > 0 && !char.IsUpper(name[i - 1]))
            {
                sb.Append('_');
            }
            sb.Append(char.ToLowerInvariant(c));
        }
        var result = sb.ToString();
        // Escape Rust keywords
        return result switch
        {
            "as" or "break" or "const" or "continue" or "crate" or "do" or "else" or
            "enum" or "extern" or "false" or "fn" or "for" or "if" or "impl" or "in" or
            "let" or "loop" or "match" or "mod" or "move" or "mut" or "pub" or "ref" or
            "return" or "self" or "static" or "struct" or "super" or "trait" or "true" or
            "type" or "unsafe" or "use" or "where" or "while" or "async" or "await" or
            "dyn" or "abstract" or "become" or "box" or "final" or "macro" or "override" or
            "priv" or "typeof" or "unsized" or "virtual" or "yield" or "try"
                => $"r#{result}",
            _ => result
        };
    }

    public string FormatEnumValue(string value, int? bits = null) => value;

    // ═══════════════════════════════════════════════════════════════════
    // DOCUMENTATION
    // ═══════════════════════════════════════════════════════════════════

    public string DocComment(
        string? doc,
        string indent = "",
        IReadOnlyList<DocParam>? parameters = null,
        string? identifier = null)
        => DocCommentFormatter.RustDoc(doc, indent, parameters);

    public string ModuleDocComment(string? doc, string? name = null)
        => DocCommentFormatter.RustModuleDoc(doc);
}
